        "sentences": [
          [
            "蚂蚁小黑找到一颗",
            "大大的糖果，",
            "可他自己抬不回去。",
            "小黑看到几个小伙伴，",
            "就向他们挥挥手，问：",
            "“你们可以和我一起",
            "把糖果抬回去吗？”",
            "小伙伴们笑着说：",
            "“当然可以！”"
          ],
          [
            "晚上十点，",
            "小明还在玩游戏，不睡觉。",
            "妈妈对他说：",
            "“明天还要上学，",
            "你得上床睡觉了。”",
            "可小明不听，他对妈妈说：",
            "“妈妈，我一点儿也不困。”",
            "妈妈把灯关了，",
            "屋子里很黑，",
            "小明只好上床睡觉了。"
          ]
        ]
