        "sentences": [
          [
            "白天，",
            "小鹿花花和动物",
            "伙伴们去山上玩。",
            "天快黑了，他们一起回家。",
            "走着走着，",
            "他们听到一只小鸟",
            "在唱歌。",
            "花花很喜欢小鸟的歌声，",
            "他走得很慢，",
            "一会儿就走在了",
            "伙伴们的后面。"
          ],
          [
            "蚂蚁们爬到洞外，",
            "看到天空中有好",
            "几朵乌云。",
            "蚂蚁爷爷对小蚂蚁们说：",
            "“马上就要下大雨了，",
            "我们得把洞里所有的",
            "东西都搬到一个",
            "更高的地方去。”"
          ]
        ]
