        "sentences": [
          [
            "比起冬天，",
            "军军更喜欢夏天。",
            "因为只有夏天到来时，",
            "军军才能吃到美味的",
            "西瓜冰沙。",
            "军军笑着对妈妈说：",
            "“西瓜冰沙是我的最爱，",
            "要是一年四季都是",
            "夏天就好啦！”"
          ],
          [
            "小黄鸭很喜欢游泳。",
            "每当夏天到来，",
            "小黄鸭就会和哥哥、",
            "姐姐一起跳入河中，",
            "快乐自在地游泳。有时候，",
            "他们还会比赛游泳呢！",
            "一开始，小黄鸭游得很慢，",
            "可它游啊游啊，",
            "慢慢地也能追上哥哥",
            "和姐姐了。"
          ]
        ]
