        "sentences": [
          [
            "老爷爷种了一个萝卜，他对萝卜说：“萝卜萝卜，快快长。长得甜甜的，长得大大的！”"
          ],
          [
            "不久，老爷爷看到萝卜越长越大，大得不得了，就去拔萝卜。他拉住萝卜的叶子，拔呀拔，怎么也拔不动。"
          ],
          [
            "老爷爷喊来老奶奶：“老婆子，快来一起拔萝卜！”老奶奶拉着老爷爷，老爷爷拉着萝卜叶子，两个人一起拔萝卜，还是拔不动。"
          ],
          [
            "老奶奶喊来小女孩：“孩子，快来一起拔萝卜！”小女孩拉着老奶奶，老奶奶拉着老爷爷，老爷爷拉着萝卜叶子，三个人一起拔萝卜，还是拔不动。"
          ],
          [
            "小女孩喊来小花狗：“小花狗，快来帮忙拔萝卜！”小花狗拉着小女孩，小女孩拉着老奶奶，老奶奶拉着老爷爷，老爷爷拉着萝卜叶子，一起拔萝卜，还是拔不动。"
          ],
          [
            "小花狗喊来小老鼠：“小老鼠，快来帮忙拔萝卜！”小老鼠拉着小花狗，小花狗拉着小女孩，小女孩拉着老奶奶，老奶奶拉着老爷爷，老爷爷拉着萝卜叶子，一起拔呀拔，终于把萝卜拔出来了！"
          ],
          [
            "大家高高兴兴地抬着萝卜，回家去了。"
          ]
        ],
        "articleTitle": "拔萝卜"
