        "sentences": [
          [
            "很久以前，有个放羊娃天天去山上放羊。"
          ],
          [
            "有一天，他想了一个坏点子。他向着山下正在种田的人们大喊：“狼来了！狼来了！”人们听见了，立刻往山上跑，边跑边喊：“孩子不要怕！我们来啦！”人们跑到山上，发现没有狼。放羊娃大笑起来：“你们上当了！”人们生气地走了。"
          ],
          [
            "第二天，放羊娃又向着山下正在种田的人们大喊：“狼来了！狼来了！”人们又立刻跑上山来打狼。放羊娃又大笑起来：“你们上当了！”"
          ],
          [
            "大伙儿对放羊娃一回又一回地说谎感到十分生气，都不再相信他了。"
          ],
          [
            "过了不久，狼真的来了。放羊娃吓坏了，他又向着山下种田的人们大喊：“狼来了！狼来了！狼真的来了！”"
          ],
          [
            "人们听见放羊娃的喊声，觉得他又在说谎，都当作没有听见，也没有人去帮他。最后，放羊娃的很多羊都被狼吃了。"
          ]
        ],
        "articleTitle": "狼来了"
