            "“妈妈，妈妈，我害怕。”鸡小弟哭得很伤心。鸡妈妈拍了拍鸡小弟的头说：“不怕，不怕，安全了！以后要听妈妈的话，在安全的地方玩，知道了吗？”鸡小弟用力点了点头，扑到了鸡妈妈的怀里。"
