        "sentences": [
          [
            "古时候，有个买卖人在城门口卖矛和盾，他大叫道：“快来看看啊！卖矛和盾了啊！”他对着路过的人得意地说：“我的矛是这天下最好的矛，你们看，它多么尖利啊！”果然，这矛的头闪着白光。买卖人接着说：“这个矛，不管什么东西都能穿破！”路人听了，纷纷说：“真是好矛啊！”"
          ],
          [
            "买卖人又开始夸自己的盾：“快来看看我的盾，这可是天下最好的盾，不管用什么东西都不能破坏它。”"
          ],
          [
            "大家正觉得这盾真好时，有一个路人问买卖人：“你的矛和你的盾都这么好，那拿你的矛去穿你的盾，它们会怎么样呢？是你的矛能穿破你的盾，还是你的盾不会被你的矛穿破呢？”大家也纷纷说：“对啊，对啊！你说说看。”"
          ],
          [
            "这下，买卖人一句话也说不出来了。大家都笑话他吹牛，因为在这个世界上，能穿破所有盾的矛和不会被矛破坏的盾是不可能同时存在的。"
          ]
        ],
        "articleTitle": "自相矛盾"
