        "sentences": [
          [
            "一只青蛙住在一口井里，自由自在地生活着。每天没事的时候，它就坐在井里看着头顶的那一小片天空。"
          ],
          [
            "一天，一只小鸟飞来，落在井口上。“青蛙先生，请问，我可以喝点儿水吗？”小鸟问。“请喝吧。”青蛙抬头看了看小鸟，又问它：“你从哪儿来呀？”"
          ],
          [
            "小鸟说：“我从天上来。我飞了很远，口渴了，下来找点儿水喝。”"
          ],
          [
            "青蛙听了，大笑道：“你就别吹牛了，天不过井口那么大，哪用得着飞那么久呢？”"
          ],
          [
            "小鸟说：“你错了，天可是大得很呢，一眼看不到头。”"
          ],
          [
            "青蛙说：“我从小就住在这口井里，每天一抬头就看见天了，我是不会错的。”小鸟说：“你真的错了，不信的话，你跳上来看看吧。”小鸟说完就飞走了。"
          ],
          [
            "青蛙听了小鸟的话，跳上了井口。它看着白白的云和蓝蓝的天，说：“原来天空这样宽广啊！”"
          ]
        ],
        "articleTitle": "坐井观天"
