        "sentences": [
          [
            "古时候，有一位有名的画家，名叫文同。他是当时画竹子的高手，他画出来的竹子就像真的一样。"
          ],
          [
            "为了画好竹子，文同不管是天气晴朗，还是刮风下雨，都在竹林里钻来钻去，观察竹子的样子。"
          ],
          [
            "有一回，天空刮起了狂风，接着又开始打雷和闪电。眼看着大雨就要来了，人们一边喊着“要下雨啦”，一边往家跑。不过文同和大家不一样。正在家里的文同急急忙忙找来一顶草帽，往头上一扣，就往山上的竹林跑去。他一走出宅院的大门，大雨就下了起来。文同一心只想观察风雨中的竹子，也不管雨有多大，就上气不接下气地跑进竹林里。在风雨中，文同把竹子被风雨吹打的样子都记在了心里。"
          ],
          [
            "由于文同长年累月地观察竹子，他十分明白竹子在不同季节、不同天气下的样子。所以，他画竹子时完全用不着画草图，竹子就像长在他心里了一样。大家都夸他：“文同画竹，早已胸有成竹了。”"
          ]
        ],
        "articleTitle": "胸有成竹"
