          [
            "新鞋子不好意思地对旧鞋子说：“对不起，看来，小熊真正喜欢的是你。”旧鞋子说：“不是的，我们两双鞋小熊都喜欢。等他再长大一点儿，穿我时就会挤脚了。那时候，他就会更喜欢你了。”"
          ],
