        "sentences": [
          [
            "森林里要举行新年晚会了，小动物们正在用五颜六色的气球装点会场，小刺猬也来帮忙了。可没想到，他身上的刺儿刺破了许多气球。"
          ],
          [
            "小刺猬去搬蛋糕，他像刺果子一样，把刺儿刺向蛋糕。呀！蛋糕没搬起来，全烂了。"
          ],
          [
            "没办法，小刺猬只好去搬桌子，谁知又不小心碰到了小猫，小猫疼得“喵喵”直哭。"
          ],
          [
            "小动物们都生气了，冲着小刺猬大声地说：“你这身刺儿真讨厌。”"
          ],
          [
            "小刺猬只好躲到了一棵树旁，心想：“要是我没这身刺儿该多好！现在，大家都不理我了。”想着想着，小刺猬伤心地哭了。"
          ],
          [
            "就在这时，会场冲进来一只大灰狼，他大笑着说：“我现在好饿，想大吃一顿，先吃谁呢？”"
          ],
          [
            "小动物们被吓得一动也不敢动。"
          ],
          [
            "忽然，大伙儿听见一个声音说：“先吃我吧。”大伙儿一看，原来是小刺猬。"
          ],
          [
            "大灰狼看着小刺猬，生气地问：“你？你这满身刺儿能吃吗？”"
          ],
          [
            "小刺猬大声地说：“我身上就数这些刺儿味道最好，香香的，像鸡腿。”"
          ],
          [
            "大灰狼一听，口水都流出来了，立刻向小刺猬扑过来。小刺猬灵机一动，团成了一个刺儿球。大灰狼一口咬在了刺儿球上，不料，嘴巴全给刺破了。大灰狼赶紧灰溜溜地逃走了。"
          ],
          [
            "伙伴们围在了小刺猬身旁，关心地问：“小刺猬，你没事吧？”"
          ],
          [
            "小刺猬笑着说：“没事，我的刺儿可硬了呢！”"
          ],
          [
            "小动物们都说：“你真勇敢，我们不应该赶走你，请你和我们一起参加晚会吧！”"
          ],
          [
            "小刺猬高兴地点了点头。"
          ],
          [
            "五彩的气球飞起来了，动听的歌儿唱起来了，好看的舞跳起来了，森林里真热闹！"
          ]
        ],
        "articleTitle": "勇敢的小刺猬"
