        "sentences": [
          [
            "丁丁在草丛里发现了一个奇怪的生物。它的身体小小的，可是有一张大大的嘴巴。忽然，这个生物说话了：“你好，我是来自外太空的大嘴巴怪兽。”丁丁对大嘴巴怪兽说：“欢迎你来地球做客。”"
          ],
          [
            "丁丁把大嘴巴怪兽带回了家。大嘴巴怪兽果然很奇怪，因为它只吃垃圾。"
          ],
          [
            "可丁丁家里的垃圾太少了。它只好跑到外面找吃的。它看到路上满是垃圾，高兴极了。大嘴巴怪兽不停地吃啊吃啊，身体和嘴巴越来越大，它变得像楼房那么大了！"
          ],
          [
            "吃了这么多垃圾，大嘴巴怪兽有些渴了。它来到一条又脏又臭的小河边，一口就把河水吸干了。"
          ],
          [
            "大嘴巴怪兽越变越大，它看到远处几座矿场的上空飘着黑乎乎的粉尘，心想：“这几座矿场一定很美味！”于是，它张大嘴巴，把这几座矿场都吃进了肚子里。"
          ],
          [
            "最后，大嘴巴怪兽飞向天空，在空中眯着眼睛，扫了一眼地球，说：“这个地球好脏呀，我把它也吃了吧！”"
          ],
          [
            "丁丁忐忑不安，可他迎难而上，大声呼喊：“不行！大嘴巴怪兽，你不能吃地球，这是我的家呀！你如果吃掉地球，不是把我也吃掉了吗？”"
          ],
          [
            "“对呀！”大嘴巴怪兽停了下来，它可不想把好朋友也吃到肚子里去。"
          ],
          [
            "丁丁说：“大嘴巴怪兽，你到别的地方去找吃的吧。我们以后一定会好好爱护地球，让地球变得干净又漂亮。”"
          ],
          [
            "大嘴巴怪兽想了想，说：“那好吧！我走了，再见！”说完，它转身向宇宙飞去了。"
          ],
          [
            "地球上的人们松了一口气。后来，他们再也不敢破坏环境了，脏脏的地球真的变成了一个干净又漂亮的星球。"
          ],
          [
            "而大嘴巴怪兽呢？它再也没回来过。"
          ]
        ],
        "articleTitle": "爱吃垃圾的大嘴巴怪兽"
