            "“当然了！”鱼儿自信地回答。“在我们这里，有一位鱼奶奶会魔法。每年的中秋节这一天，天上的月亮最圆也最亮，在月光和鱼奶奶魔法的帮助下，我们就可以跟岸上的小动物互换身份了。”"
